use vstd::prelude::*;

verus! {
    // Specification for the maximum function over a non-empty array of signed integers
    spec fn max_in_array(nums: Vec<i32>) -> i32
        requires
            nums.len() > 0,
        ensures
            forall |i: nat| (i < nums.len() as nat) ==> (max_in_array(nums) >= nums[i as usize]) &&
            exists |j: nat| (j < nums.len() as nat) && (max_in_array(nums) == nums[j as usize])
    {
        // The maximum value is defined as the maximum of the array elements
        let mut max_val = nums[0];
        let len = nums.len();
        for i in 1..len {
            if nums[i] > max_val {
                max_val = nums[i];
            }
        }
        max_val
    }

    fn find_max(nums: Vec<i32>) -> (ret: i32)
        requires
            nums.len() > 0,
        ensures
            ret == max_in_array(nums)
    {
        let mut max_val: i32 = nums[0]; // Initialize max_val with the first element
        let len = nums.len();
        let mut idx: usize = 1; // Start from the second element

        while idx < len
            invariant
                idx <= len,
                max_val == max_in_array(nums[..idx].to_vec()), // Maintain the invariant that max_val is the maximum of the first idx elements
            decreases len - idx,
        {
            if nums[idx] > max_val {
                max_val = nums[idx]; // Update max_val if the current element is greater
            }
            idx += 1; // Move to the next element
        }
        max_val // Return the maximum value found
    }
}

